def validate(value, rule, path='$'):
 if '$ref' in rule:
  target=schema
  for component in rule['$ref'].split('/')[1:]: target=target[component]
  return validate(value,target,path)
 kind=rule.get('type')
 if kind=='object':
  assert isinstance(value,dict),path
  assert set(rule.get('required',[]))<=value.keys(),path+' required'
  properties=rule.get('properties',{})
  if rule.get('additionalProperties') is False: assert value.keys()<=properties.keys(),path+' unknown fields'
  for key,item in value.items(): validate(item,properties[key],path+'.'+key)
 elif kind=='array':
  assert isinstance(value,list),path
  assert len(value)<=rule.get('maxItems',float('inf')),path+' size'
  for i,item in enumerate(value): validate(item,rule['items'],path+'['+str(i)+']')
 elif kind=='string':
